# -*- coding: utf-8 -*-
"""`python -m build new-project`: writes <CODE>/project.json and .github/workflows/refresh-<CODE>.yml.

Each new workflow runs 4 minutes after the latest existing one (twice a day, IST), so
refreshes do not pile onto VisiLean at the same moment.
"""
from __future__ import annotations

import json
import os
import re

from . import ROOT
from .build import KEY_RE
from .fetch import secret_name

WORKFLOW = """name: "Refresh {code} - {name}"

# Generated by `python -m build new-project`. Refreshes the {code} page and data tables from
# VisiLean (1 API call: task history), publishes the page to the gh-pages branch, uploads the
# four tables as a workflow artifact, then asks the portfolio workflow to rebuild the landing page.
# Token: repository secret {secret}.

on:
  schedule:
    - cron: "{m} {h1} * * *"   # {ist1} IST
    - cron: "{m} {h2} * * *"   # {ist2} IST
  workflow_dispatch:

permissions:
  contents: write   # push to gh-pages
  actions: write    # start the portfolio workflow

concurrency:
  group: refresh-{code}
  cancel-in-progress: false

jobs:
  refresh:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-python@v5
        with:
          python-version: "3.12"

      # last good copy of the feed: an outage gives a "stale" page instead of an empty one
      - name: Restore last good data
        uses: actions/cache@v4
        with:
          path: .cache
          key: vl-feed-{code}-${{{{ github.run_id }}}}
          restore-keys: |
            vl-feed-{code}-

      - name: Self-test calculation logic
        run: python -m build selftest

      - name: Fetch the published site
        run: bash .github/scripts/pages.sh fetch

      - name: Build {code}
        id: build
        env:
          {secret}: ${{{{ secrets.{secret} }}}}
        run: |
          set -uo pipefail
          python -m build build --project "{code}" --source live --no-landing | tee build.log
          code=${{PIPESTATUS[0]}}
          echo "code=$code" >> "$GITHUB_OUTPUT"
          [ "$code" = "0" ] || [ "$code" = "2" ] || exit "$code"

      # Tables 1-4 (Table 1 is raw and never published)
      - name: Upload data tables
        uses: actions/upload-artifact@v4
        with:
          name: {code}-tables
          path: data/{code}/
          retention-days: 14
          if-no-files-found: ignore

      - name: Validate
        run: python -m build validate --project "{code}"

      - name: Scan for credentials
        run: bash .github/scripts/pages.sh scan "{code}"

      - name: Publish {code}
        run: bash .github/scripts/pages.sh publish "Refresh {code}" "{code}"

      - name: Refresh the portfolio page
        env:
          GH_TOKEN: ${{{{ github.token }}}}
        run: gh workflow run portfolio.yml --ref "${{{{ github.ref_name }}}}"

      - name: Report problems
        run: |
          state=$(python -c "import json; print(json.load(open('dist/{code}/build.json'))['state'])")
          echo "### {code}: $state" >> "$GITHUB_STEP_SUMMARY"
          if [ "${{{{ steps.build.outputs.code }}}}" = "2" ]; then
            echo "::error title=VisiLean token rejected::Fix repository secret {secret}"; exit 1
          fi
          if [ "$state" = "unavailable" ]; then
            echo "::error title=No data::{code} has no data: check secret {secret} and the project GUID"; exit 1
          fi
"""

FIRST_SLOT = (4 * 60 + 21)  # 04:21 UTC = 09:51 IST


def _next_slot(wf_dir: str) -> int:
    """Minutes past midnight UTC for the morning run: 4 minutes after the latest existing one."""
    latest = None
    for f in os.listdir(wf_dir) if os.path.isdir(wf_dir) else []:
        if f.startswith("refresh-") and f.endswith(".yml"):
            with open(os.path.join(wf_dir, f), encoding="utf-8") as fh:
                m = re.search(r'cron: "(\d+) (\d+) ', fh.read())
            if m:
                t = int(m.group(2)) * 60 + int(m.group(1))
                latest = t if latest is None else max(latest, t)
    return FIRST_SLOT if latest is None else latest + 4


def _ist(minutes_utc: int) -> str:
    t = (minutes_utc + 330) % (24 * 60)
    return "%02d:%02d" % (t // 60, t % 60)


def new_project(code: str, name: str, guid: str, client: str | None, force: bool) -> int:
    if not KEY_RE.match(code):
        print("code must match %s" % KEY_RE.pattern)
        return 1
    pdir = os.path.join(ROOT, code)
    pj = os.path.join(pdir, "project.json")
    wf_dir = os.path.join(ROOT, ".github", "workflows")
    wf = os.path.join(wf_dir, "refresh-%s.yml" % code)
    if not force and (os.path.exists(pj) or os.path.exists(wf)):
        print("%s already exists; use --force to overwrite" % (pj if os.path.exists(pj) else wf))
        return 1
    slot = _next_slot(wf_dir) if not os.path.exists(wf) else FIRST_SLOT
    os.makedirs(pdir, exist_ok=True)
    cfg = {"key": code, "title": name, "projectId": guid, "facts": []}
    if client:
        cfg["client"] = client
    with open(pj, "w", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps(cfg, indent=2, ensure_ascii=False) + "\n")
    os.makedirs(wf_dir, exist_ok=True)
    m, h1 = slot % 60, slot // 60
    with open(wf, "w", encoding="utf-8", newline="\n") as f:
        f.write(WORKFLOW.format(code=code, name=name, secret=secret_name(code), m=m, h1=h1, h2=(h1 + 6) % 24,
                                ist1=_ist(slot), ist2=_ist(slot + 360)))
    print("wrote %s and %s" % (os.path.relpath(pj, ROOT), os.path.relpath(wf, ROOT)))
    print("next: create repository secret %s holding the VisiLean access token" % secret_name(code))
    return 0
